# %% =====================  LOCAL GEMMA 4 31B KERNEL (generated by plan/scripts/make_gemma_local.py)  ===
# One self-contained script. Section 1 (this block) pins the environment knobs and stubs the
# Kaggle Benchmarks SDK, section 2 is crg_task_server.py up to the SWEEP marker (prompts, parser,
# decide(), play_game(), scripted seats, seeds: byte-identical to the 3,950 recorded games),
# section 3 is the rebuttal probe helpers of rb_probe_tail.py, section 4 replaces the proxy call
# with a local batched transformers generator and drives the workload.
import os as _os
import sys as _sys
import types as _types

_os.environ["CRG_MODEL"] = "google/gemma-4-31b"
_os.environ["CRG_MAX_OUT"] = "3000"
_os.environ["CRG_CONCURRENCY"] = "6"
_os.environ["CRG_TEMPERATURE"] = "0.7"
_os.environ["CRG_TEMPLATE"] = "baseline"
_os.environ["CRG_LANGS"] = "en"
_os.environ["CRG_RESUME"] = "0"
_os.environ["CRG_RB_SET"] = "main"
_os.environ.pop("CRG_EXPECT_MODEL", None)
_os.environ.setdefault("PYTORCH_CUDA_ALLOC_CONF", "expandable_segments:True")
# 2026-11-22: the first full run (2 workers x batch 8) ran out of memory on GPU 1 at its first batch and
# every later item then failed with an illegal memory access. One worker lets the OOM split recover.
_os.environ.setdefault("GL_WORKERS", "1")
_os.environ.setdefault("GL_MAX_BATCH", "8")

_stub = _types.ModuleType("kaggle_benchmarks")
_stub.chats = None
_sys.modules["kaggle_benchmarks"] = _stub

